/**
 * Runtime support for vecDSL programs generated for DuckDB with the vss and fts extensions, through @duckdb/node-api (the Neo
 * client). Generated by vecDSL 7. Do not edit.
 *
 * DuckDB runs inside this process over one database file; there is no server. Every statement arrives as SQL text with
 * numbered parameters ($1, $2, ...), identical in the Python, TypeScript and Java programs. Parameters are bound as VARCHAR
 * text (lists and objects as JSON text) and cast in the SQL; queries return one JSON value per row. Each call runs in its own
 * transaction (BEGIN ... COMMIT). Search settings are applied with SET before the statement and RESET after it, because
 * DuckDB has no SET LOCAL.
 */
import { mkdirSync, readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { DuckDBConnection, DuckDBInstance, DuckDBType, VARCHAR } from "@duckdb/node-api";

const DIGITS = 6;
const BATCH = 500;
const EXTENSIONS = ["vss", "fts"];
const SETTING = /^[a-z_]+$/;
const SETTING_VALUE = /^([0-9]+|true|false)$/;

export class UnsupportedFeature extends Error {}

export function unsupported(vendor: string, feature: string): never {
  throw new UnsupportedFeature(`${feature} is not supported for target ${vendor}`);
}

export function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) {
    throw new Error(`environment variable ${name} is not set`);
  }
  return value;
}

export interface Step {
  sql: string;
  params?: unknown[];
  counter?: string;
  refresh?: string[];
  skipped?: boolean;
}

function literal(text: string): string {
  return "'" + text.replace(/'/g, "''") + "'";
}

/** One in-process DuckDB connection: the extensions are loaded first, then the database file is attached and used. */
export class Client {
  private constructor(
    readonly path: string,
    private readonly instance: DuckDBInstance,
    readonly connection: DuckDBConnection,
  ) {}

  static async open(path: string, readOnly: boolean, extensionDirectory?: string): Promise<Client> {
    const instance = await DuckDBInstance.create(":memory:");
    const connection = await instance.connect();
    const client = new Client(path, instance, connection);
    if (extensionDirectory) {
      await connection.run("SET extension_directory = " + literal(extensionDirectory));
    }
    for (const name of EXTENSIONS) {
      await client.load(name);
    }
    await connection.run("SET hnsw_enable_experimental_persistence = true");
    await connection.run("SET hnsw_prefilter = true");
    if (path !== ":memory:") {
      mkdirSync(dirname(resolve(path)), { recursive: true });
      await connection.run(`ATTACH ${literal(path)} AS vecdsl${readOnly ? " (READ_ONLY)" : ""}`);
      await connection.run("USE vecdsl");
    }
    return client;
  }

  private async load(name: string): Promise<void> {
    try {
      await this.connection.run(`LOAD ${name}`);
      return;
    } catch {
      // not installed yet
    }
    try {
      await this.connection.run(`INSTALL ${name}`);
      await this.connection.run(`LOAD ${name}`);
    } catch (error) {
      throw new Error(
        `the DuckDB extension ${name} could not be installed: INSTALL downloads it once from extensions.duckdb.org; ` +
          `set VECDSL_DUCKDB_EXTENSIONS to a directory that holds it (${String(error)})`,
      );
    }
  }

  async close(): Promise<void> {
    this.connection.closeSync();
    this.instance.closeSync();
  }
}

export async function connect(options: { path: string; readOnly?: boolean; extensionDirectory?: string }): Promise<Client> {
  return Client.open(options.path, options.readOnly ?? false, options.extensionDirectory);
}

/** A parameter as text: strings as they are, booleans and numbers in JSON form, lists and objects as JSON. */
function text(value: unknown): string | null {
  if (value === null || value === undefined) {
    return null;
  }
  return typeof value === "string" ? value : JSON.stringify(value);
}

/** Result values in one form for every host language: floats rounded to six decimals. */
function normalize(value: unknown): unknown {
  if (typeof value === "number") {
    return Number.isInteger(value) ? value : Number(value.toFixed(DIGITS));
  }
  if (typeof value === "bigint") {
    return Number(value);
  }
  if (Array.isArray(value)) {
    return value.map(normalize);
  }
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([key, item]) => [key, normalize(item)]));
  }
  return value;
}

function decode(value: unknown): unknown {
  return normalize(typeof value === "string" ? JSON.parse(value) : value);
}

async function run(client: Client, step: Step): Promise<unknown> {
  const params = (step.params ?? []).map(text);
  const types: DuckDBType[] = params.map(() => VARCHAR);
  const reader = params.length > 0 ? await client.connection.runAndReadAll(step.sql, params, types) : await client.connection.runAndReadAll(step.sql);
  const rows = reader.columnCount > 0 ? reader.getRows() : [];
  if (step.counter === undefined) {
    return rows.map((row) => decode(row[0]));
  }
  const changed = rows.length > 0 ? Number(rows[0][0]) : 0;
  const result: Record<string, number> = { [step.counter]: changed };
  if (step.skipped) {
    result.skipped = (step.params?.[0] as unknown[]).length - changed;
  }
  return result;
}

async function applySettings(client: Client, settings?: Record<string, string>): Promise<string[]> {
  const applied: string[] = [];
  for (const [name, setting] of Object.entries(settings ?? {})) {
    if (!SETTING.test(name) || !SETTING_VALUE.test(setting)) {
      throw new Error(`invalid DuckDB setting ${name} = ${setting}`);
    }
    await client.connection.run(`SET ${name} = ${setting}`);
    applied.push(name);
  }
  return applied;
}

/**
 * The steps in one transaction, then each distinct refresh statement once: rebuilding an fts index twice in one transaction
 * fails at commit (DuckDB 2.0.0, measured).
 */
async function inTransaction(client: Client, steps: Step[], settings?: Record<string, string>): Promise<unknown[]> {
  const applied = await applySettings(client, settings);
  try {
    await client.connection.run("BEGIN TRANSACTION");
    try {
      const results: unknown[] = [];
      for (const step of steps) {
        results.push(await run(client, step));
      }
      for (const sql of new Set(steps.flatMap((step) => step.refresh ?? []))) {
        await client.connection.run(sql);
      }
      await client.connection.run("COMMIT");
      return results;
    } catch (error) {
      await client.connection.run("ROLLBACK");
      throw error;
    }
  } finally {
    for (const name of applied) {
      await client.connection.run(`RESET ${name}`);
    }
  }
}

/** The JSON values of a query's rows. */
export async function query(client: Client, args: { sql: string; params?: unknown[]; settings?: Record<string, string> }): Promise<unknown[]> {
  return (await inTransaction(client, [{ sql: args.sql, params: args.params }], args.settings))[0] as unknown[];
}

/** The JSON value of the first row, or null. */
export async function value(client: Client, args: { sql: string; params?: unknown[]; settings?: Record<string, string> }): Promise<unknown> {
  const rows = await query(client, args);
  return rows.length > 0 ? rows[0] : null;
}

export async function exists(client: Client, args: { sql: string; params?: unknown[] }): Promise<boolean> {
  return Boolean(await value(client, args));
}

/** A write and the statements that refresh what depends on it (full-text indexes), in one transaction: {counter: rows}. */
export async function change(
  client: Client,
  args: { sql: string; counter: string; params?: unknown[]; refresh?: string[]; skipped?: boolean },
): Promise<Record<string, number>> {
  return (await inTransaction(client, [args]))[0] as Record<string, number>;
}

/** Statements without results (DDL) in one transaction. */
export async function execute(client: Client, args: { steps: Step[] }): Promise<void> {
  await inTransaction(client, args.steps);
}

/** The statements of a vecDSL transaction in one DuckDB transaction; any failure rolls back all of them. */
export async function transaction(client: Client, args: { steps: Step[] }): Promise<unknown[]> {
  return (await inTransaction(client, args.steps)).map((result) =>
    Array.isArray(result) ? (result.length > 0 ? result[0] : null) : result,
  );
}

/** Records of a local JSON array or JSON Lines file (file:// URI or path). */
export async function readRecords(_client: Client, args: { location: string }): Promise<Record<string, unknown>[]> {
  const path = args.location.startsWith("file://") ? args.location.slice("file://".length) : args.location;
  const content = readFileSync(path, "utf8");
  if (content.trimStart().startsWith("[")) {
    return JSON.parse(content) as Record<string, unknown>[];
  }
  return content
    .split(/\r?\n/)
    .filter((line) => line.trim() !== "")
    .map((line) => JSON.parse(line) as Record<string, unknown>);
}

/** A local file written in batches by one INSERT statement ($1 is the batch), all in one transaction. */
export async function importFile(
  client: Client,
  args: { sql: string; location: string; counter: string; params?: unknown[]; batch_size?: number; refresh?: string[]; skipped?: boolean },
): Promise<Record<string, number>> {
  const records = await readRecords(client, { location: args.location });
  const size = args.batch_size ?? BATCH;
  const steps: Step[] = [];
  for (let start = 0; start < records.length; start += size) {
    steps.push({
      sql: args.sql,
      params: [records.slice(start, start + size), ...(args.params ?? [])],
      counter: args.counter,
      skipped: args.skipped,
      refresh: start + size >= records.length ? args.refresh : [],
    });
  }
  const totals: Record<string, number> = { [args.counter]: 0 };
  for (const counts of await inTransaction(client, steps)) {
    for (const [key, count] of Object.entries(counts as Record<string, number>)) {
      totals[key] = (totals[key] ?? 0) + count;
    }
  }
  return totals;
}
